const listPendingServerSessions = `-- name: ListPendingServerSessions :many
SELECT id, profile_id, server_id, ip, joined_at, verified_at, disconnected_at FROM minecraft.server_session
WHERE profile_id = $1
  AND verified_at IS NULL
  AND joined_at > now() - $2::interval
ORDER BY joined_at DESC
LIMIT 20
`

type ListPendingServerSessionsParams struct {
	ProfileID uuid.UUID       `json:"profile_id"`
	Window    pgtype.Interval `json:"window"`
}

// 列出某玩家尚未核销、且仍在时间窗内的进服会话。
//
// hasJoined 收到的是**签名**(serverIdHash),不是原始 serverId,
// 要重算就得把该玩家的候选会话逐个试一遍。因此候选集必须小 ——
// 时间窗和「一次核销」两条约束共同把它压到个位数。
func (q *Queries) ListPendingServerSessions(ctx context.Context, arg ListPendingServerSessionsParams) ([]MinecraftServerSession, error) {
	rows, err := q.db.Query(ctx, listPendingServerSessions, arg.ProfileID, arg.Window)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MinecraftServerSession{}
	for rows.Next() {
		var i MinecraftServerSession
		if err := rows.Scan(
			&i.ID,
			&i.ProfileID,
			&i.ServerID,
			&i.Ip,
			&i.JoinedAt,
			&i.VerifiedAt,
			&i.DisconnectedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPendingServerSessionsBefore = `-- name: ListPendingServerSessionsBefore :many
SELECT id, profile_id, server_id, ip, joined_at, verified_at, disconnected_at FROM minecraft.server_session
WHERE profile_id = $1
  AND verified_at IS NULL
  AND joined_at >= $2::timestamptz
ORDER BY joined_at DESC
LIMIT 20
`

type ListPendingServerSessionsBeforeParams struct {
	ProfileID uuid.UUID `json:"profile_id"`
	Cutoff    time.Time `json:"cutoff"`
}

// 同上,但用**调用方算好的截止时间**而不是数据库的 now()。
//
// 时间窗的判定必须用应用时钟:服务注入的是可替换的 Clock,
// 测试要靠推进它来验证过期行为;而数据库的 now() 推不动。
// 顺带消除了「数据库时钟与进程时钟漂移」带来的判定不一致。
func (q *Queries) ListPendingServerSessionsBefore(ctx context.Context, arg ListPendingServerSessionsBeforeParams) ([]MinecraftServerSession, error) {
	rows, err := q.db.Query(ctx, listPendingServerSessionsBefore, arg.ProfileID, arg.Cutoff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MinecraftServerSession{}
	for rows.Next() {
		var i MinecraftServerSession
		if err := rows.Scan(
			&i.ID,
			&i.ProfileID,
			&i.ServerID,
			&i.Ip,
			&i.JoinedAt,
			&i.VerifiedAt,
			&i.DisconnectedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

