const rotateMCAccessToken = `-- name: RotateMCAccessToken :one
WITH old AS (
    UPDATE minecraft.access_token
    SET revoked_at = now(), revoked_reason = 'refreshed'
    WHERE token_hash = $3::bytea AND revoked_at IS NULL
    RETURNING profile_id, client_token
)
INSERT INTO minecraft.access_token (token_hash, profile_id, client_token, expires_at)
SELECT $1::bytea, old.profile_id, old.client_token,
       $2::timestamptz
FROM old
RETURNING id, token_hash, profile_id, client_token, expires_at, revoked_at, revoked_reason, created_at
`

type RotateMCAccessTokenParams struct {
	NewHash   []byte    `json:"new_hash"`
	ExpiresAt time.Time `json:"expires_at"`
	OldHash   []byte    `json:"old_hash"`
}

// 刷新:吊销旧令牌并签发新的一条,在同一条语句里完成。
//
// 分成两步的话,中间崩溃会留下「旧令牌已废、新令牌没发」的空窗,
// 玩家会被直接踢下线。
func (q *Queries) RotateMCAccessToken(ctx context.Context, arg RotateMCAccessTokenParams) (MinecraftAccessToken, error) {
	row := q.db.QueryRow(ctx, rotateMCAccessToken, arg.NewHash, arg.ExpiresAt, arg.OldHash)
	var i MinecraftAccessToken
	err := row.Scan(
		&i.ID,
		&i.TokenHash,
		&i.ProfileID,
		&i.ClientToken,
		&i.ExpiresAt,
		&i.RevokedAt,
		&i.RevokedReason,
		&i.CreatedAt,
	)
	return i, err
}

